using System;using System.Linq;using System.IO;using System.Reflection;using System.Threading.Tasks;using UnityEditor;using UnityEngine;using RoadGunner.Editor;
public static class LevelEditorSceneInputAsync{
 public static async Task<string> Main(){var l=RoadGunnerLevelAuthoring.Current;var w=EditorWindow.GetWindow<RoadGunnerLevelEditorWindow>();var sv=SceneView.lastActiveSceneView;var world=RoadGunnerTerrainBrush.GroundPoint(l,-5,5);sv.orthographic=true;sv.LookAtDirect(world,Quaternion.Euler(65,0,0),15);var method=typeof(RoadGunnerLevelEditorWindow).GetMethod("StartMode",BindingFlags.NonPublic|BindingFlags.Instance);var mtype=method.GetParameters()[0].ParameterType;var so=new SerializedObject(w);so.FindProperty("selectedPrefab").objectReferenceValue=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/RoadGunner/Prefabs/Wasteland Raider.prefab");so.FindProperty("gridSnap").boolValue=false;so.ApplyModifiedPropertiesWithoutUndo();method.Invoke(w,new object[]{Enum.Parse(mtype,"Prefab")});int before=l.humanEnemiesRoot.childCount;var ready=new TaskCompletionSource<Vector2>();Action<SceneView> callback=null;callback=view=>{if(view!=sv||Event.current.type!=EventType.Repaint)return;SceneView.duringSceneGui-=callback;ready.TrySetResult(HandleUtility.WorldToGUIPoint(world));};SceneView.duringSceneGui+=callback;sv.Focus();sv.Repaint();await Task.WhenAny(ready.Task,Task.Delay(5000));if(!ready.Task.IsCompleted){SceneView.duringSceneGui-=callback;throw new Exception("Scene View did not repaint");}var pt=ready.Task.Result;await Task.Delay(50);
 sv.SendEvent(new Event{type=EventType.MouseMove,mousePosition=pt});sv.SendEvent(new Event{type=EventType.MouseDown,mousePosition=pt,button=0});sv.SendEvent(new Event{type=EventType.MouseUp,mousePosition=pt,button=0});bool placed=l.humanEnemiesRoot.childCount==before+1;string text=(placed?"PASS ":"FAIL ")+"Scene View click instantiates connected human prefab\n";sv.SendEvent(new Event{type=EventType.KeyDown,keyCode=KeyCode.Escape});var modeField=typeof(RoadGunnerLevelEditorWindow).GetField("mode",BindingFlags.NonPublic|BindingFlags.Instance);text+=(modeField.GetValue(w).ToString()=="None"?"PASS ":"FAIL ")+"Escape exits placement\n";if(placed){Undo.DestroyObjectImmediate(l.humanEnemiesRoot.GetChild(l.humanEnemiesRoot.childCount-1).gameObject);RoadGunnerLevelAuthoring.Wire(l);}
 var mesh=l.ground.sharedMesh;var beforeVertices=mesh.vertices;method.Invoke(w,new object[]{Enum.Parse(mtype,"Terrain")});sv.SendEvent(new Event{type=EventType.MouseDown,mousePosition=pt,button=0});sv.SendEvent(new Event{type=EventType.MouseUp,mousePosition=pt,button=0});var afterVertices=mesh.vertices;bool altered=!beforeVertices.SequenceEqual(afterVertices);bool colliderMatches=false;if(altered){int i=Enumerable.Range(0,afterVertices.Length).First(n=>Mathf.Abs(beforeVertices[n].y-afterVertices[n].y)>.00001f);var p=l.ground.transform.TransformPoint(afterVertices[i]);colliderMatches=Mathf.Abs(RoadGunnerTerrainBrush.GroundPoint(l,p.x,p.z).y-p.y)<.001f;}text+=(altered&&colliderMatches?"PASS ":"FAIL ")+"Scene View brush changes mesh and collider\n";Undo.FlushUndoRecordObjects();Undo.PerformUndo();text+=(mesh.vertices.SequenceEqual(beforeVertices)?"PASS ":"FAIL ")+"Scene View stroke Undo restores ground\n";sv.SendEvent(new Event{type=EventType.KeyDown,keyCode=KeyCode.Escape});RoadGunnerLevelAuthoring.Save(l);File.WriteAllText(Path.Combine(Directory.GetParent(Application.dataPath).FullName,RoadGunnerLevelEditorChecks.Folder,"SceneInputChecks.txt"),text);return text;}}
